19	// 本文件通过公开 HTTP 接口对“创建房间并保存到本地”的行为做端到端回归测试：
20	// 以子进程方式启动真实服务（--port 0 自动选端口），不改动任何现有代码。
21	
22	var serverBin string
23	
24	func TestMain(m *testing.M) {
25		dir, err := os.MkdirTemp("", "score-arena-testbin")
26		if err != nil {
27			fmt.Fprintln(os.Stderr, err)
28			os.Exit(1)
29		}
