43	// startServer 在 dataDir 上启动服务子进程，返回基地址（如 http://127.0.0.1:12345）。
44	func startServer(t *testing.T, dataDir string) string {
45		t.Helper()
46		cmd := exec.Command(serverBin, "serve", "--host", "127.0.0.1", "--port", "0", "--data-dir", dataDir)
47		stdout, err := cmd.StdoutPipe()
48		if err != nil {
49			t.Fatalf("获取服务输出失败: %v", err)
50		}
51		cmd.Stderr = os.Stderr
52		if err := cmd.Start(); err != nil {
53			t.Fatalf("启动服务失败: %v", err)
54		}
55		t.Cleanup(func() {
56			_ = cmd.Process.Kill()
57			_ = cmd.Wait()
58		})
59	
60		lineCh := make(chan string, 1)
61		go func() {
62			scanner := bufio.NewScanner(stdout)
63			for scanner.Scan() {
64				if line := scanner.Text(); strings.Contains(line, "listening on") {
65					lineCh <- line
66					return
67				}
68			}
69			lineCh <- ""
70		}()
71	
72		select {
73		case line := <-lineCh:
74			if line == "" {
75				t.Fatal("服务在输出监听地址前退出")
76			}
77			idx := strings.Index(line, "http://")
78			if idx < 0 {
79				t.Fatalf("无法从服务输出解析地址: %q", line)
80			}
81			return strings.TrimSpace(line[idx:])
82		case <-time.After(15 * time.Second):
83			t.Fatal("等待服务监听地址超时")
84			return ""
85		}
86	}
