88	// seedRooms 在 dataDir 下写入给定的房间记录（每条为一段 JSON 文本），返回文件内容。
89	func seedRooms(t *testing.T, dataDir string, records ...string) []byte {
90		t.Helper()
91		content := "[\n" + strings.Join(records, ",\n") + "\n]\n"
92		if err := os.WriteFile(filepath.Join(dataDir, "rooms.json"), []byte(content), 0o644); err != nil {
93			t.Fatalf("写入种子数据失败: %v", err)
94		}
95		return []byte(content)
96	}
