98	func decodeRecords(t *testing.T, raw []byte) []any {
99		t.Helper()
100		var records []any
101		if err := json.Unmarshal(raw, &records); err != nil {
102			t.Fatalf("解析记录失败: %v", err)
103		}
104		return records
105	}
