107	var httpClient = &http.Client{Timeout: 5 * time.Second}
108	
109	// postRoom 提交创建请求，返回状态码与解码后的响应体。
110	func postRoom(t *testing.T, baseURL, body string) (int, map[string]any) {
111		t.Helper()
112		resp, err := httpClient.Post(baseURL+"/api/rooms", "application/json", strings.NewReader(body))
113		if err != nil {
114			t.Fatalf("POST /api/rooms 失败: %v", err)
115		}
116		defer resp.Body.Close()
117		payload, err := io.ReadAll(resp.Body)
118		if err != nil {
119			t.Fatalf("读取响应失败: %v", err)
120		}
121		var decoded map[string]any
122		if err := json.Unmarshal(payload, &decoded); err != nil {
123			t.Fatalf("响应不是合法 JSON: %v（内容: %s）", err, payload)
124		}
125		return resp.StatusCode, decoded
126	}
