128	// getRooms 查询房间列表，返回状态码与记录数组（保持服务端顺序）。
129	func getRooms(t *testing.T, baseURL string) (int, []any) {
130		t.Helper()
131		resp, err := httpClient.Get(baseURL + "/api/rooms")
132		if err != nil {
133			t.Fatalf("GET /api/rooms 失败: %v", err)
134		}
135		defer resp.Body.Close()
136		var body struct {
137			Rooms []json.RawMessage `json:"rooms"`
138		}
139		if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
140			t.Fatalf("房间列表响应不是合法 JSON: %v", err)
141		}
142		rooms := make([]any, 0, len(body.Rooms))
143		for _, raw := range body.Rooms {
144			var record any
145			if err := json.Unmarshal(raw, &record); err != nil {
146				t.Fatalf("房间记录不是合法 JSON: %v", err)
147			}
148			rooms = append(rooms, record)
149		}
150		return resp.StatusCode, rooms
151	}
