274	// 缺少每步时间不能被当成不限时，应返回 400 且不产生新房间、不改变原有记录。
275	func TestCreateRoomRejectedWhenTurnSecondsMissing(t *testing.T) {
276		dataDir := t.TempDir()
277		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
278		baseURL := startServer(t, dataDir)
279	
280		status, body := postRoom(t, baseURL, `{"name":"缺时间的房间","game":"gomoku","capacity":2}`)
281		if status != http.StatusBadRequest {
282			t.Fatalf("状态码 = %d，期望 400，响应: %v", status, body)
283		}
284		errMsg, _ := body["error"].(string)
285		if !strings.Contains(errMsg, "turnSeconds") {
286			t.Fatalf("error 应说明缺少 turnSeconds，实际: %q", errMsg)
