591	// 历史房间数组里混有非对象记录（null、字符串、数字、布尔值、数组——含空数组与
592	// 内部装着房间对象的数组）以及带额外字段或缺字段的对象时，GET /api/rooms 必须
593	// 把全部元素按数量、次序与原始类型原样返回：页面展示层正是依据“是不是 JSON 对象”
594	// 决定能否成为房间行，接口层不能提前过滤、丢弃或展开任何一条记录。
595	// 仅读取列表不得改写磁盘文件；随后合法创建房间时，原有混合记录仍要原位保留，
596	// 新房间对象追加在最后。
597	func TestGetRoomsPreservesMixedRawRecords(t *testing.T) {
598		dataDir := t.TempDir()
599		mixed := []string{
600			seedRecord1, // 完整对象，附带 note/tags 额外字段
601			`null`,
602			`"误入的字符串"`,
603			`""`, // 空字符串不能因其为空而漏计
604			`0`,  // 数字 0 不能因其为假值而漏计
605			`42`,
606			`false`, // 布尔 false 不能因其为假值而漏计
607			`true`,
608			`[]`,                      // 空数组：一条非对象记录，不是“没有记录”
609			`[{"id":"inside-array"}]`, // 装着对象的数组：整体一条记录，不能展开
610			`{"id":"only-id"}`,        // 缺字段对象：仍是一条对象记录
611		}
612		seed := seedRooms(t, dataDir, mixed...)
613		baseURL := startServer(t, dataDir)
614	
615		status, rooms := getRooms(t, baseURL)
616		if status != http.StatusOK {
617			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", status)
618		}
619		if len(rooms) != len(mixed) {
620			t.Fatalf("返回记录数量 = %d，期望 %d（非对象记录不得被丢弃）", len(rooms), len(mixed))
621		}
622	
623		// 与种子逐元素比对（解码后的值、次序、类型与附带字段完全一致）。
624		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms, want) {
625			t.Fatalf("混合记录未被原样保留：\n得到: %v\n期望: %v", rooms, want)
626		}
627	
628		// 逐位置钉住原始类型，防止“看起来数量对”但元素被转换或重新排序。
629		if rooms[1] != nil {
630			t.Fatalf("第 2 条应为 null，实际 %v (%T)", rooms[1], rooms[1])
631		}
632		if got := rooms[2]; got != "误入的字符串" {
633			t.Fatalf("字符串记录应为 %q，实际 %v", "误入的字符串", got)
634		}
635		if got := rooms[3]; got != "" {
636			t.Fatalf("空字符串记录应保留为空串，实际 %v (%T)", got, got)
637		}
638		if got := rooms[4]; got != float64(0) {
639			t.Fatalf("数字 0 记录应保留为 0，实际 %v (%T)", got, got)
640		}
641		if got := rooms[6]; got != false {
642			t.Fatalf("布尔 false 记录应保留为 false，实际 %v (%T)", got, got)
643		}
644		arr, ok := rooms[8].([]any)
645		if !ok {
646			t.Fatalf("空数组记录应保留为数组类型，实际 %T", rooms[8])
647		}
648		if len(arr) != 0 {
649			t.Fatalf("空数组记录不应被展开或填充，实际 %v", arr)
650		}
651		nested, ok := rooms[9].([]any)
652		if !ok || len(nested) != 1 {
653			t.Fatalf("装对象的数组应整体保留为仅含 1 个元素的数组，实际 %v", rooms[9])
654		}
655		if inner, _ := nested[0].(map[string]any); inner["id"] != "inside-array" {
656			t.Fatalf("数组内对象应原样保留在数组内部，实际 %v", nested[0])
657		}
658		if partial, ok := rooms[10].(map[string]any); !ok || len(partial) != 1 || partial["id"] != "only-id" {
659			t.Fatalf("缺字段对象应原样保留为对象记录，实际 %v", rooms[10])
660		}
661		if first, _ := rooms[0].(map[string]any); first["note"] != "保留我" {
662			t.Fatalf("首条对象的附带字段应原样保留，实际 %v", rooms[0])
663		}
664	
665		// 只读取列表不得产生任何写入：磁盘文件与种子逐字节一致。
666		if got := readDataFile(t, dataDir); !bytes.Equal(got, seed) {
667			t.Fatalf("读取列表改写了数据文件：\n得到: %s\n期望: %s", got, seed)
668		}
