248			}
249			if got := created["capacity"]; got != float64(4) {
250				t.Fatalf("%s：人数 = %v，期望 4", tc.desc, got)
251			}
252			if got := created["turnSeconds"]; got != float64(60) {
253				t.Fatalf("%s：每步时间 = %v，期望 60", tc.desc, got)
254			}
255			wantCreated = append(wantCreated, created)
256		}
257	
258		// 列表仅在原有 2 条记录之后按提交次序增加成功创建的记录，每条与创建响应一致。
259		listStatus, rooms := getRooms(t, baseURL)
260		if listStatus != http.StatusOK {
261			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", listStatus)
262		}
263		if want := 2 + len(wantCreated); len(rooms) != want {
264			t.Fatalf("房间数量 = %d，期望 %d（种子 2 条 + 成功创建 %d 条）", len(rooms), want, len(wantCreated))
265		}
266		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
267			t.Fatalf("原有房间被改动或重新排序：\n得到: %v\n期望: %v", rooms[:2], want)
268		}
269		for i, created := range wantCreated {
270			if !reflect.DeepEqual(rooms[2+i], created) {
271				t.Fatalf("列表第 %d 条新记录与创建响应不一致：\n列表: %v\n响应: %v", i+1, rooms[2+i], created)
272			}
273		}
274	
275		// 本地保存的内容与查询结果一致，且原有记录的附带字段逐字段保留。
276		saved := decodeRecords(t, readDataFile(t, dataDir))
277		if !reflect.DeepEqual(saved, rooms) {
278			t.Fatalf("本地保存记录与房间列表不一致：\n文件: %v\n列表: %v", saved, rooms)
279		}
280		first, _ := saved[0].(map[string]any)
281		if first["note"] != "保留我" {
282			t.Fatalf("首条种子记录的附带字段被改写: %v", saved[0])
283		}
284	}
285	
286	// 被各种不符合约定的请求拒绝后，用户把请求修正为一个合法对象：
287	// 应收到 201 和新房间，列表仅在原有记录之后增加这一条（内容与创建响应一致），
288	// 此前被拒绝的请求不占据任何房间记录。
289	func TestCreateRoomRecoversAfterMalformedBodies(t *testing.T) {
290		dataDir := t.TempDir()
291		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
292		baseURL := startServer(t, dataDir)
293	
294		// 先制造一批覆盖各拒绝分支的错误请求。
295		badBodies := []string{
296			"",
297			"   ",
298			"not json",
299			"null",
300			`"晚间五子棋"`,
301			"42",
302			"true",
303			"[" + validRoomBody + "]",
304			validRoomBody + secondValidRoomBody,
305			validRoomBody + `x`,
306			`{"name":"半截房","game":"gomoku","capacity":2,"turnSeconds":3`,
307		}
308		for _, body := range badBodies {
309			assertSingleObjectRejected(t, baseURL, dataDir, seed, body)
310		}
311	
312		// 修正为一个合法对象后正常创建。
313		status, created := postRoom(t, baseURL, validRoomBody)
314		if status != http.StatusCreated {
315			t.Fatalf("修正后创建状态码 = %d，期望 201，响应: %v", status, created)
316		}
317		id, _ := created["id"].(string)
318		if id == "" || id == "seed-alpha" || id == "seed-beta" {
319			t.Fatalf("修正后新房间编号异常: %q", id)
320		}
321		if got, want := created["name"], "晚间五子棋"; got != want {
322			t.Fatalf("名称 = %v，期望 %q", got, want)
323		}
324	
325		// 列表仅在原有记录之后增加这一次成功创建的记录；被拒绝请求不占记录。
326		listStatus, rooms := getRooms(t, baseURL)
327		if listStatus != http.StatusOK {
328			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", listStatus)
329		}
330		if len(rooms) != 3 {
331			t.Fatalf("房间数量 = %d，期望 3（种子 2 条 + 修正成功 1 条，被拒请求不得留记录）", len(rooms))
332		}
333		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
334			t.Fatalf("原有房间的数量、次序、配置或附带字段被改动：\n得到: %v\n期望: %v", rooms[:2], want)
335		}
336		if !reflect.DeepEqual(rooms[2], created) {
337			t.Fatalf("列表中的新记录与创建响应不一致：\n列表: %v\n响应: %v", rooms[2], created)
338		}
339		if got := readDataFile(t, dataDir); bytes.Contains(got, []byte("深夜飞行棋")) || bytes.Contains(got, []byte("半截房")) {
340			t.Fatalf("被拒绝请求的内容不应写入本地文件，实际: %s", got)
341		}
342	}
343	
344	// 错误信息要保持稳定可辨：所有入口拒绝都返回同一条“请求体必须是单个 JSON 对象”，
345	// 与已有的字段校验错误（缺少字段 / 类型不符 / 房间名称不能为空）能明确区分。
346	func TestCreateRoomSingleObjectErrorIsDistinctFromFieldErrors(t *testing.T) {
347		dataDir := t.TempDir()
348		seedRooms(t, dataDir, seedRecord1, seedRecord2)
349		baseURL := startServer(t, dataDir)
350	
351		// 入口错误。
352		for _, body := range []string{"null", "[" + validRoomBody + "]", validRoomBody + "x"} {
353			status, resp := postRoom(t, baseURL, body)
354			if status != http.StatusBadRequest {
355				t.Fatalf("状态码 = %d，期望 400（载荷: %q）", status, body)
356			}
357			if errMsg, _ := resp["error"].(string); errMsg != singleObjectErr {
358				t.Fatalf("载荷 %q 的 error = %q，期望固定信息 %q", body, errMsg, singleObjectErr)
359			}
360		}
361	
362		// 字段级错误仍沿用各自原有的提示，入口规则的收紧不得改变这些既有行为。
363		fieldCases := []struct {
364			body    string
365			wantSub string
366		}{
367			{`{"name":"缺时间房","game":"gomoku","capacity":2}`, "缺少必填字段"},
368			{`{"name":"","game":"gomoku","capacity":2,"turnSeconds":0}`, "不能为空"},
369			{`{"name":"字符串人数房","game":"gomoku","capacity":"2","turnSeconds":0}`, "整数"},
370			{`{"name":"未知规则房","game":"chess","capacity":2,"turnSeconds":0}`, "游戏规则"},
371		}
372		for _, tc := range fieldCases {
373			status, resp := postRoom(t, baseURL, tc.body)
374			if status != http.StatusBadRequest {
375				t.Fatalf("状态码 = %d，期望 400（载荷: %q，响应: %v）", status, tc.body, resp)
376			}
377			errMsg, _ := resp["error"].(string)
378			if !strings.Contains(errMsg, tc.wantSub) {
379				t.Fatalf("载荷 %q 的 error 应仍包含 %q，实际: %q", tc.body, tc.wantSub, errMsg)
380			}
381			if strings.Contains(errMsg, singleObjectErr) {
382				t.Fatalf("载荷 %q 是单个对象，不应报入口格式错误，实际: %q", tc.body, errMsg)
383			}
384		}
385	}
